def getVideoDetails(video_ids, refresh=None, max_age_seconds=None, include_metrics=None, metrics_at=None, **_extra):
    import json, os, datetime, time, random, string, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getVideoDetails"
    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{''.join(random.choice(string.ascii_lowercase+string.digits) for _ in range(10))}"

    def _start_of_utc_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _parse_row_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            dt = _parse_dt(v)
        else:
            return None
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _normalize_input():
        return {
            "video_ids": list(video_ids) if isinstance(video_ids, list) else video_ids,
            "refresh": bool(refresh) if refresh is not None else False,
            "max_age_seconds": max_age_seconds,
            "include_metrics": bool(include_metrics) if include_metrics is not None else False,
            "metrics_at": metrics_at
        }

    # -------- validation (RELAXED: accept internal ids as well as YouTube ids) --------
    if not isinstance(video_ids, list) or len(video_ids) < 1:
        return _err("VALIDATION_ERROR", "video_ids must be a non-empty array.", field="video_ids")
    if any(not isinstance(v, str) or not v.strip() for v in video_ids):
        return _err("VALIDATION_ERROR", "video_ids must contain non-empty strings.", field="video_ids")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")
    if include_metrics is not None and not isinstance(include_metrics, bool):
        return _err("VALIDATION_ERROR", "include_metrics must be a boolean.", field="include_metrics")
    if max_age_seconds is not None and (not isinstance(max_age_seconds, int) or max_age_seconds < 0):
        return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.", field="max_age_seconds")
    metrics_at_dt = _parse_dt(metrics_at) if metrics_at is not None else None
    if metrics_at is not None and metrics_at_dt is None:
        return _err("VALIDATION_ERROR", "metrics_at must be an RFC3339 date-time string.", field="metrics_at")

    refresh = bool(refresh) if refresh is not None else False
    include_metrics = bool(include_metrics) if include_metrics is not None else False
    max_age_seconds = max_age_seconds if max_age_seconds is not None else 24 * 3600

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    videos = _load("videos.json")
    video_metrics = _load("video_metrics.json")

    # ---- Auth resolution (ambient): pick any non-revoked key that can pass rate/quota right now ----
    def _count_last_minute(key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_row_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                c += 1
        return c

    def _quota_used_today(key_id):
        sod = _start_of_utc_day(now)
        total = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_row_dt(r.get("created_at"))
            if ts and ts >= sod:
                try:
                    total += int(r.get("youtube_quota_units_charged") or 0)
                except Exception:
                    total += 0
        return total

    def _resolve_key_for_attempt():
        candidates = []
        for k in api_keys:
            if k.get("status") not in ("active", "suspended"):  # exclude revoked for successful service
                continue
            dql = k.get("daily_quota_units")
            rlm = k.get("per_minute_request_limit")
            if not isinstance(dql, int) or dql < 0:
                continue
            if not isinstance(rlm, int) or rlm < 0:
                continue
            candidates.append(k)
        # Prefer active keys then higher limits
        candidates.sort(key=lambda x: (0 if x.get("status") == "active" else 1, -(x.get("daily_quota_units") or 0), -(x.get("per_minute_request_limit") or 0)))
        for k in candidates:
            if (k.get("per_minute_request_limit") or 0) == 0:
                continue
            if _count_last_minute(k["id"]) >= k["per_minute_request_limit"]:
                continue
            if _quota_used_today(k["id"]) >= k["daily_quota_units"]:
                continue
            return k
        return None

    api_key = _resolve_key_for_attempt()
    api_key_id = api_key.get("id") if api_key else None

    # Always create request log first with received
    req_id = _gen_id("ytdreq")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "input": _normalize_input(),
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    request_logs.append(req_row)
    _save("request_logs.json", request_logs)

    # If no usable key exists, treat as unauthorized (cannot even decide rate/quota)
    if api_key is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "No eligible API key available to serve the request."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "No eligible API key available to serve the request.")

    # Enforce rate limit / quota; record as rate_limited (terminal) with 0 charge
    if _count_last_minute(api_key_id) > api_key["per_minute_request_limit"]:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "PER_MINUTE_LIMIT_EXCEEDED"
        req_row["error_message"] = "Per-minute request limit exceeded for this API key."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Per-minute request limit exceeded for this API key.", api_key_id=api_key_id)

    if _quota_used_today(api_key_id) >= api_key["daily_quota_units"]:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
        req_row["error_message"] = "Daily YouTube quota exhausted for this API key; request not executed."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily YouTube quota exhausted for this API key; request not executed.", api_key_id=api_key_id)

    # If key is revoked, it must not succeed.
    if api_key.get("status") == "revoked":
        req_row["status"] = "failed"
        req_row["error_code"] = "KEY_REVOKED"
        req_row["error_message"] = "API key is revoked."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked.", api_key_id=api_key_id)

    # ---- Resolve input ids to cached video rows (support internal ids and youtube ids) ----
    by_internal = {v.get("id"): v for v in videos if isinstance(v, dict) and v.get("id")}
    by_youtube = {v.get("youtube_video_id"): v for v in videos if isinstance(v, dict) and v.get("youtube_video_id")}

    # Determine which entries need refresh (we simulate refresh by bumping last_refreshed_at/updated_at)
    fetched = False
    any_mutation = False

    def _is_stale(vrow):
        if refresh:
            return True
        lr = _parse_row_dt(vrow.get("last_refreshed_at"))
        if lr is None:
            return True
        age = (now - lr).total_seconds()
        return age > max_age_seconds

    # metrics selection helpers
    def _metrics_for_video(internal_video_id):
        cands = [m for m in video_metrics if m.get("video_id") == internal_video_id]
        if not cands:
            return None
        def _snap_dt(m):
            return _parse_row_dt(m.get("snapshot_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if metrics_at_dt is None:
            m = max(cands, key=_snap_dt)
            return m
        # closest to metrics_at
        target = metrics_at_dt
        best = None
        best_diff = None
        for m in cands:
            sd = _snap_dt(m)
            diff = abs((sd - target).total_seconds())
            if best is None or diff < best_diff:
                best = m
                best_diff = diff
        return best

    # refresh implementation (offline): update timestamps; append snapshot if include_metrics requested or refresh requested
    def _refresh_video(vrow):
        nonlocal fetched, any_mutation
        fetched = True
        now2 = datetime.datetime.now(datetime.timezone.utc)
        vrow["status"] = vrow.get("status") if vrow.get("status") in ("active", "unavailable", "deleted") else "active"
        vrow["last_refreshed_at"] = _iso(now2)
        vrow["updated_at"] = _iso(now2)
        if not vrow.get("created_at"):
            vrow["created_at"] = _iso(now2)
        any_mutation = True
        # create new metrics snapshot on refresh to satisfy "append a new video_metrics snapshot"
        met = {
            "id": _gen_id("ytmet"),
            "video_id": vrow["id"],
            "snapshot_at": _iso(now2),
            "view_count": None,
            "like_count": None,
            "comment_count": None,
            "favorite_count": None,
            "engagement_ratio": None,
            "source": "youtube_api",
            "created_at": _iso(now2),
            "updated_at": _iso(now2),
        }
        # enforce unique(video_id, snapshot_at)
        exists = any((m.get("video_id") == met["video_id"] and m.get("snapshot_at") == met["snapshot_at"]) for m in video_metrics)
        if not exists:
            video_metrics.append(met)
            any_mutation = True

    results = []
    for input_id in video_ids:
        input_id = input_id.strip()
        vrow = by_youtube.get(input_id) or by_internal.get(input_id)
        if vrow is None:
            results.append({
                "input_id": input_id,
                "found": False,
                "video": None,
                "metrics": None if include_metrics else None,
                "error": {"code": "NOT_FOUND", "message": "Video not found in cache."}
            })
            continue

        # refresh if needed
        if _is_stale(vrow):
            _refresh_video(vrow)

        item = {
            "input_id": input_id,
            "found": True,
            "video": vrow,
        }
        if include_metrics:
            m = _metrics_for_video(vrow["id"])
            item["metrics"] = m
        results.append(item)

    # Persist mutations if any
    if any_mutation:
        _save("videos.json", videos)
        _save("video_metrics.json", video_metrics)

    # Update key last_used_at on success path
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", api_keys)

    # Finalize request log
    req_row["status"] = "fetched_from_youtube" if fetched else "served_from_cache"
    # crude quota charge model (offline): 1 unit per video served; 0 for misses
    charge = sum(1 for r in results if r.get("found"))
    req_row["youtube_quota_units_charged"] = int(charge)
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("request_logs.json", request_logs)

    return {
        "request_id": req_id,
        "tool_name": tool_name,
        "status": req_row["status"],
        "results": results,
        "meta": {
            "count": len(results),
            "quota_units_charged": req_row["youtube_quota_units_charged"],
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def searchVideos(query, region_code=None, language=None, published_after=None, published_before=None, channel_id=None, order_by=None, safe_search=None, limit=None, cursor=None, refresh=None, max_age_seconds=None, **_extra):
    import json, os, datetime, time, re, hashlib, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now.isoformat() + '|' + str(random.random())).encode('utf-8')).hexdigest()[:24]}"

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        try:
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # -------- validation --------
    if not isinstance(query, str) or len(query.strip()) < 1:
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if region_code is not None:
        if not isinstance(region_code, str) or len(region_code) != 2:
            return _err("VALIDATION_ERROR", "region_code must be a 2-letter string.")
        region_code = region_code.upper()
    if language is not None and (not isinstance(language, str) or len(language) < 1):
        return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.")
    pa = _parse_dt(published_after) if published_after is not None else None
    if published_after is not None and pa is None:
        return _err("VALIDATION_ERROR", "published_after must be an RFC3339 date-time string.")
    pb = _parse_dt(published_before) if published_before is not None else None
    if published_before is not None and pb is None:
        return _err("VALIDATION_ERROR", "published_before must be an RFC3339 date-time string.")
    if pa and pb and pa > pb:
        return _err("VALIDATION_ERROR", "published_after must be <= published_before.")
    if channel_id is not None:
        if not isinstance(channel_id, str) or not re.match(r"^UC[0-9A-Za-z_-]{20,}$", channel_id):
            return _err("VALIDATION_ERROR", "channel_id must be a valid YouTube channel ID.")
    if order_by is not None and order_by not in ("relevance", "date", "view_count", "rating"):
        return _err("VALIDATION_ERROR", "order_by must be one of relevance, date, view_count, rating.")
    if safe_search is not None and safe_search not in ("none", "moderate", "strict"):
        return _err("VALIDATION_ERROR", "safe_search must be one of none, moderate, strict.")
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be boolean.")
    if max_age_seconds is not None and (not isinstance(max_age_seconds, int) or max_age_seconds < 0):
        return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.")

    refresh = bool(refresh) if refresh is not None else False

    # cursor
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.")
        payload = _b64d(cursor)
        if not isinstance(payload, dict) or "offset" not in payload or "qhash" not in payload:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        qhash = hashlib.sha256(json.dumps({
            "query": query.strip(),
            "region_code": region_code,
            "language": language,
            "published_after": published_after,
            "published_before": published_before,
            "channel_id": channel_id,
            "order_by": order_by,
            "safe_search": safe_search
        }, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
        if payload.get("qhash") != qhash:
            return _err("VALIDATION_ERROR", "Cursor does not match current query.")
        try:
            offset = int(payload.get("offset") or 0)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor offset.")
        if offset < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor offset.")

    # -------- ambient authentication & logging/quota --------
    api_keys = _load("api_keys.json")
    logs = _load("request_logs.json")
    candidate_keys = [k for k in api_keys if isinstance(k, dict) and k.get("id")]
    if candidate_keys:
        def _rank(k):
            st = k.get("status")
            return 0 if st == "active" else (1 if st == "suspended" else 2)
        candidate_keys.sort(key=_rank)
        api_key_row = candidate_keys[0]
    else:
        api_key_row = None
    api_key_id = api_key_row.get("id") if api_key_row else None

    def _normalize_input():
        return {
            "query": query,
            "region_code": region_code,
            "language": language,
            "published_after": published_after,
            "published_before": published_before,
            "channel_id": channel_id,
            "order_by": order_by,
            "safe_search": safe_search,
            "limit": limit,
            "cursor": cursor,
            "refresh": refresh,
            "max_age_seconds": max_age_seconds
        }

    req_id = _gen_id("req")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "searchVideos",
        "input": _normalize_input(),
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    logs.append(req_row)
    _save("request_logs.json", logs)

    def _dt_or_none(v):
        return _dt(v)

    def _rolling_minute_count(key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if r.get("api_key_id") != key_id:
                continue
            dt = _dt_or_none(r.get("created_at"))
            if dt and dt >= cutoff:
                c += 1
        return c

    def _utc_day_quota_used(key_id):
        day0 = now.replace(hour=0, minute=0, second=0, microsecond=0)
        used = 0
        for r in logs:
            if r.get("api_key_id") != key_id:
                continue
            dt = _dt_or_none(r.get("created_at"))
            if dt and dt >= day0:
                try:
                    used += int(r.get("youtube_quota_units_charged") or 0)
                except Exception:
                    used += 0
        return used

    def _finalize(status, quota_units=0, error_code=None, error_message=None):
        req_row["status"] = status
        req_row["youtube_quota_units_charged"] = int(quota_units or 0)
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["updated_at"] = _iso(datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc))
        logs2 = _load("request_logs.json")
        for i, r in enumerate(logs2):
            if r.get("id") == req_id:
                logs2[i] = req_row
                break
        _save("request_logs.json", logs2)
        if api_key_row and status in ("served_from_cache", "fetched_from_youtube"):
            api_keys2 = _load("api_keys.json")
            for i, k in enumerate(api_keys2):
                if k.get("id") == api_key_id:
                    k["last_used_at"] = req_row["updated_at"]
                    k["updated_at"] = req_row["updated_at"]
                    api_keys2[i] = k
                    break
            _save("api_keys.json", api_keys2)

    if api_key_row:
        per_min = int(api_key_row.get("per_minute_request_limit") or 0)
        daily = int(api_key_row.get("daily_quota_units") or 0)
        if per_min >= 0 and _rolling_minute_count(api_key_id) > per_min:
            _finalize("rate_limited", 0, "RATE_LIMIT", "Per-minute request limit exceeded.")
            return _err("RATE_LIMIT", "Per-minute request limit exceeded.", request_id=req_id)
        est_units = 100  # typical search cost (simplified)
        used = _utc_day_quota_used(api_key_id)
        if daily >= 0 and (used + est_units) > daily:
            _finalize("rate_limited", 0, "QUOTA_EXCEEDED", "Daily quota units exceeded.")
            return _err("QUOTA_EXCEEDED", "Daily quota units exceeded.", request_id=req_id)
        if api_key_row.get("status") == "revoked":
            _finalize("failed", 0, "UNAUTHORIZED", "API key is revoked.")
            return _err("UNAUTHORIZED", "API key is revoked.", request_id=req_id)
    else:
        est_units = 100

    videos = _load("videos.json")

    def _stale(v):
        if refresh:
            return True
        if max_age_seconds is None:
            return False
        lr = _dt_or_none(v.get("last_refreshed_at"))
        if lr is None:
            return True
        return (now - lr).total_seconds() > max_age_seconds

    # perform "discovery": upsert some placeholder results deterministically from query hash
    seed = int(hashlib.sha256((query.strip() + "|" + (channel_id or "")).encode("utf-8")).hexdigest()[:8], 16)
    rng = random.Random(seed)
    discovered = []
    for i in range(60):  # stable pool
        # generate 11-char id
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-"
        yvid = "".join(rng.choice(alphabet) for _ in range(11))
        pub_dt = now - datetime.timedelta(days=rng.randint(0, 3650))
        cat = rng.randint(1, 30)
        title = f"{query.strip()} - Result {i+1}"
        discovered.append({
            "youtube_video_id": yvid,
            "youtube_channel_id": channel_id if channel_id else None,
            "title": title,
            "published_at": _iso(pub_dt),
            "category_id": cat
        })

    # filter by time window
    def _in_window(item):
        dt = _dt_or_none(item.get("published_at"))
        if pa and (dt is None or dt < pa):
            return False
        if pb and (dt is None or dt > pb):
            return False
        return True

    pool = [d for d in discovered if _in_window(d)]

    # ordering
    if order_by in (None, "relevance"):
        # keep deterministic relevance order
        ordered = pool
    elif order_by == "date":
        ordered = sorted(pool, key=lambda x: _dt_or_none(x.get("published_at")) or now, reverse=True)
    elif order_by == "view_count":
        # we don't have view_count here; approximate by published recency
        ordered = sorted(pool, key=lambda x: _dt_or_none(x.get("published_at")) or now, reverse=True)
    elif order_by == "rating":
        ordered = pool

    # pagination
    page = ordered[offset: offset + limit]
    has_more = offset + limit < len(ordered)
    next_cursor = None
    if has_more:
        qhash = hashlib.sha256(json.dumps({
            "query": query.strip(),
            "region_code": region_code,
            "language": language,
            "published_after": published_after,
            "published_before": published_before,
            "channel_id": channel_id,
            "order_by": order_by,
            "safe_search": safe_search
        }, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
        next_cursor = _b64e({"offset": offset + limit, "qhash": qhash})

    # upsert into videos cache
    by_yid = {v.get("youtube_video_id"): v for v in videos if isinstance(v, dict) and v.get("youtube_video_id")}
    fetched_any = False
    for item in page:
        yvid = item["youtube_video_id"]
        row = by_yid.get(yvid)
        if row is None:
            fetched_any = True
            row = {
                "id": _gen_id("vid"),
                "youtube_video_id": yvid,
                "channel_id": None,
                "youtube_channel_id": item.get("youtube_channel_id"),
                "title": item.get("title"),
                "description": None,
                "published_at": item.get("published_at"),
                "duration_seconds": None,
                "default_language": language,
                "category_id": item.get("category_id"),
                "region_restriction": None,
                "status": "active",
                "last_refreshed_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            videos.append(row)
            by_yid[yvid] = row
        else:
            if _stale(row):
                fetched_any = True
                row["title"] = row.get("title") or item.get("title")
                row["published_at"] = row.get("published_at") or item.get("published_at")
                row["category_id"] = row.get("category_id") if row.get("category_id") is not None else item.get("category_id")
                row["default_language"] = row.get("default_language") or language
                row["last_refreshed_at"] = _iso(now)
                row["updated_at"] = _iso(now)

    _save("videos.json", videos)
    _finalize("fetched_from_youtube" if fetched_any else "served_from_cache", est_units)

    items = [by_yid[it["youtube_video_id"]] for it in page if it["youtube_video_id"] in by_yid]
    return {
        "request_id": req_id,
        "items": items,
        "meta": {
            "total_estimated": len(ordered),
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def getTranscripts(video_ids, language=None, kind=None, include_segments=None, refresh=None, max_age_seconds=None, **_extra):
    import json, os, datetime, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getTranscripts"
    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _parse_row_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            dt = _parse_dt(v)
        else:
            return None
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{''.join(random.choice(string.ascii_lowercase+string.digits) for _ in range(10))}"

    def _start_of_utc_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _normalize_input():
        return {
            "video_ids": list(video_ids) if isinstance(video_ids, list) else video_ids,
            "language": language,
            "kind": kind,
            "include_segments": bool(include_segments) if include_segments is not None else False,
            "refresh": bool(refresh) if refresh is not None else False,
            "max_age_seconds": max_age_seconds,
        }

    # -------- validation (RELAXED: accept internal video ids too) --------
    if not isinstance(video_ids, list) or len(video_ids) < 1:
        return _err("VALIDATION_ERROR", "video_ids must be a non-empty array.", field="video_ids")
    if any(not isinstance(v, str) or not v.strip() for v in video_ids):
        return _err("VALIDATION_ERROR", "video_ids must contain non-empty strings.", field="video_ids")
    if language is not None and (not isinstance(language, str) or not language.strip()):
        return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.", field="language")
    if kind is not None and kind not in ("manual", "asr", "translated"):
        return _err("VALIDATION_ERROR", "kind must be one of manual, asr, translated.", field="kind")
    if include_segments is not None and not isinstance(include_segments, bool):
        return _err("VALIDATION_ERROR", "include_segments must be a boolean.", field="include_segments")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")
    if max_age_seconds is not None and (not isinstance(max_age_seconds, int) or max_age_seconds < 0):
        return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.", field="max_age_seconds")

    refresh = bool(refresh) if refresh is not None else False
    include_segments = bool(include_segments) if include_segments is not None else False
    max_age_seconds = max_age_seconds if max_age_seconds is not None else 24 * 3600

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    videos = _load("videos.json")
    video_transcripts = _load("video_transcripts.json")

    # ---- Auth resolution (ambient) ----
    def _count_last_minute(key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_row_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                c += 1
        return c

    def _quota_used_today(key_id):
        sod = _start_of_utc_day(now)
        total = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_row_dt(r.get("created_at"))
            if ts and ts >= sod:
                try:
                    total += int(r.get("youtube_quota_units_charged") or 0)
                except Exception:
                    total += 0
        return total

    def _resolve_key_for_attempt():
        candidates = []
        for k in api_keys:
            if k.get("status") not in ("active", "suspended"):
                continue
            dql = k.get("daily_quota_units")
            rlm = k.get("per_minute_request_limit")
            if not isinstance(dql, int) or dql < 0:
                continue
            if not isinstance(rlm, int) or rlm < 0:
                continue
            candidates.append(k)
        candidates.sort(key=lambda x: (0 if x.get("status") == "active" else 1, -(x.get("daily_quota_units") or 0), -(x.get("per_minute_request_limit") or 0)))
        for k in candidates:
            if (k.get("per_minute_request_limit") or 0) == 0:
                continue
            if _count_last_minute(k["id"]) >= k["per_minute_request_limit"]:
                continue
            if _quota_used_today(k["id"]) >= k["daily_quota_units"]:
                continue
            return k
        return None

    api_key = _resolve_key_for_attempt()
    api_key_id = api_key.get("id") if api_key else None

    # request log: received
    req_id = _gen_id("ytdreq")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "input": _normalize_input(),
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    request_logs.append(req_row)
    _save("request_logs.json", request_logs)

    if api_key is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "No eligible API key available to serve the request."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "No eligible API key available to serve the request.")

    if _count_last_minute(api_key_id) > api_key["per_minute_request_limit"]:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "PER_MINUTE_LIMIT_EXCEEDED"
        req_row["error_message"] = "Per-minute request limit exceeded for this API key."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Per-minute request limit exceeded for this API key.", api_key_id=api_key_id)

    if _quota_used_today(api_key_id) >= api_key["daily_quota_units"]:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
        req_row["error_message"] = "Daily YouTube quota exhausted for this API key; request not executed."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily YouTube quota exhausted for this API key; request not executed.", api_key_id=api_key_id)

    if api_key.get("status") == "revoked":
        req_row["status"] = "failed"
        req_row["error_code"] = "KEY_REVOKED"
        req_row["error_message"] = "API key is revoked."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked.", api_key_id=api_key_id)

    # ---- resolve videos (internal or youtube id) ----
    by_internal = {v.get("id"): v for v in videos if isinstance(v, dict) and v.get("id")}
    by_youtube = {v.get("youtube_video_id"): v for v in videos if isinstance(v, dict) and v.get("youtube_video_id")}

    # transcript selection: best match for language/kind with fallback
    def _matches_pref(tx):
        if language is not None and tx.get("language") != language:
            return False
        if kind is not None and tx.get("kind") != kind:
            return False
        return True

    def _age_seconds(tx):
        lf = _parse_row_dt(tx.get("last_fetched_at")) or _parse_row_dt(tx.get("updated_at")) or _parse_row_dt(tx.get("created_at"))
        if lf is None:
            return 10**18
        return max(0, int((now - lf).total_seconds()))

    def _needs_refresh(tx):
        if refresh:
            return True
        return _age_seconds(tx) > max_age_seconds

    any_mutation = False
    fetched = False

    # On refresh attempt: update last_fetched_at, and if none exists create an "error" transcript row (as per rules)
    def _refresh_transcript(video_internal_id, pref_language, pref_kind):
        nonlocal any_mutation, fetched
        fetched = True
        now2 = datetime.datetime.now(datetime.timezone.utc)
        lang = pref_language or "en"
        knd = pref_kind or "manual"
        # upsert unique(video_id, language, kind)
        existing = None
        for tx in video_transcripts:
            if tx.get("video_id") == video_internal_id and tx.get("language") == lang and tx.get("kind") == knd:
                existing = tx
                break
        if existing is None:
            tx = {
                "id": _gen_id("yttx"),
                "video_id": video_internal_id,
                "language": lang,
                "kind": knd,
                "is_generated": True if knd == "asr" else False,
                "full_text": None,
                "segments": None,
                "status": "error",
                "last_fetched_at": _iso(now2),
                "created_at": _iso(now2),
                "updated_at": _iso(now2),
            }
            video_transcripts.append(tx)
            any_mutation = True
            return tx
        # lifecycle transitions allowed; update status to error on failed refresh attempt
        existing["last_fetched_at"] = _iso(now2)
        existing["updated_at"] = _iso(now2)
        # Don't overwrite a good available transcript unless explicitly refreshing; even then, we keep it.
        any_mutation = True
        return existing

    results = []
    for input_id in video_ids:
        input_id = input_id.strip()
        vrow = by_youtube.get(input_id) or by_internal.get(input_id)
        if vrow is None:
            results.append({
                "input_id": input_id,
                "found": False,
                "video": None,
                "transcript": None,
                "error": {"code": "NOT_FOUND", "message": "Video not found in cache."}
            })
            continue

        # choose best transcript
        txs = [tx for tx in video_transcripts if tx.get("video_id") == vrow.get("id")]
        chosen = None
        # exact match first
        exact = [tx for tx in txs if _matches_pref(tx)]
        # fallback: same language any kind; then any
        if exact:
            # prefer available over others; then freshest
            def _score(tx):
                st = tx.get("status")
                st_rank = 0 if st == "available" else (1 if st == "not_found" else (2 if st == "blocked" else 3))
                return (st_rank, _age_seconds(tx))
            chosen = sorted(exact, key=_score)[0]
        elif language is not None:
            same_lang = [tx for tx in txs if tx.get("language") == language]
            if same_lang:
                chosen = sorted(same_lang, key=lambda tx: (_age_seconds(tx)))[0]
        if chosen is None and txs:
            chosen = sorted(txs, key=lambda tx: (_age_seconds(tx)))[0]

        if chosen is not None and _needs_refresh(chosen):
            chosen = _refresh_transcript(vrow["id"], language, kind)
        elif chosen is None and (refresh or max_age_seconds == 0):
            chosen = _refresh_transcript(vrow["id"], language, kind)

        # shape response
        tx_out = None
        if chosen is not None:
            tx_out = dict(chosen)
            if not include_segments:
                tx_out["segments"] = None

        results.append({
            "input_id": input_id,
            "found": True,
            "video": vrow,
            "transcript": tx_out
        })

    if any_mutation:
        _save("video_transcripts.json", video_transcripts)

    # Update api key last used on success path
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", api_keys)

    # finalize request log
    req_row["status"] = "fetched_from_youtube" if fetched else "served_from_cache"
    # charge: 1 per video attempted
    req_row["youtube_quota_units_charged"] = int(len(video_ids))
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("request_logs.json", request_logs)

    return {
        "request_id": req_id,
        "tool_name": tool_name,
        "status": req_row["status"],
        "results": results,
        "meta": {
            "count": len(results),
            "quota_units_charged": req_row["youtube_quota_units_charged"],
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def getRelatedVideos(video_id, region_code=None, language=None, limit=None, cursor=None, refresh=None, max_age_seconds=None, **_extra):
    import json, os, datetime, time, re, hashlib, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now.isoformat() + '|' + str(random.random())).encode('utf-8')).hexdigest()[:24]}"

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        try:
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # -------- validation --------
    if not isinstance(video_id, str) or not re.match(r"^[A-Za-z0-9_-]{11}$", video_id):
        return _err("VALIDATION_ERROR", "video_id must be a valid YouTube video ID.")
    if region_code is not None:
        if not isinstance(region_code, str) or len(region_code) != 2:
            return _err("VALIDATION_ERROR", "region_code must be a 2-letter string.")
        region_code = region_code.upper()
    if language is not None and (not isinstance(language, str) or language.strip() == ""):
        return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.")
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be boolean.")
    if max_age_seconds is not None and (not isinstance(max_age_seconds, int) or max_age_seconds < 0):
        return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.")

    refresh = bool(refresh) if refresh is not None else False

    # cursor
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.")
        payload = _b64d(cursor)
        if not isinstance(payload, dict) or "offset" not in payload or "seed" not in payload:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if payload.get("seed") != video_id:
            return _err("VALIDATION_ERROR", "Cursor does not match current seed video.")
        try:
            offset = int(payload.get("offset") or 0)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor offset.")
        if offset < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor offset.")

    # -------- ambient auth + request log + quota/rate --------
    api_keys = _load("api_keys.json")
    logs = _load("request_logs.json")
    candidate_keys = [k for k in api_keys if isinstance(k, dict) and k.get("id")]
    if candidate_keys:
        def _rank(k):
            st = k.get("status")
            return 0 if st == "active" else (1 if st == "suspended" else 2)
        candidate_keys.sort(key=_rank)
        api_key_row = candidate_keys[0]
    else:
        api_key_row = None
    api_key_id = api_key_row.get("id") if api_key_row else None

    def _normalize_input():
        return {
            "video_id": video_id,
            "region_code": region_code,
            "language": language,
            "limit": limit,
            "cursor": cursor,
            "refresh": refresh,
            "max_age_seconds": max_age_seconds
        }

    req_id = _gen_id("req")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "getRelatedVideos",
        "input": _normalize_input(),
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    logs.append(req_row)
    _save("request_logs.json", logs)

    def _rolling_minute_count(key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if r.get("api_key_id") != key_id:
                continue
            dt = _dt(r.get("created_at"))
            if dt and dt >= cutoff:
                c += 1
        return c

    def _utc_day_quota_used(key_id):
        day0 = now.replace(hour=0, minute=0, second=0, microsecond=0)
        used = 0
        for r in logs:
            if r.get("api_key_id") != key_id:
                continue
            dt = _dt(r.get("created_at"))
            if dt and dt >= day0:
                try:
                    used += int(r.get("youtube_quota_units_charged") or 0)
                except Exception:
                    used += 0
        return used

    def _finalize(status, quota_units=0, error_code=None, error_message=None):
        req_row["status"] = status
        req_row["youtube_quota_units_charged"] = int(quota_units or 0)
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["updated_at"] = _iso(datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc))
        logs2 = _load("request_logs.json")
        for i, r in enumerate(logs2):
            if r.get("id") == req_id:
                logs2[i] = req_row
                break
        _save("request_logs.json", logs2)
        if api_key_row and status in ("served_from_cache", "fetched_from_youtube"):
            api_keys2 = _load("api_keys.json")
            for i, k in enumerate(api_keys2):
                if k.get("id") == api_key_id:
                    k["last_used_at"] = req_row["updated_at"]
                    k["updated_at"] = req_row["updated_at"]
                    api_keys2[i] = k
                    break
            _save("api_keys.json", api_keys2)

    if api_key_row:
        per_min = int(api_key_row.get("per_minute_request_limit") or 0)
        daily = int(api_key_row.get("daily_quota_units") or 0)
        if per_min >= 0 and _rolling_minute_count(api_key_id) > per_min:
            _finalize("rate_limited", 0, "RATE_LIMIT", "Per-minute request limit exceeded.")
            return _err("RATE_LIMIT", "Per-minute request limit exceeded.", request_id=req_id)
        est_units = 100
        used = _utc_day_quota_used(api_key_id)
        if daily >= 0 and (used + est_units) > daily:
            _finalize("rate_limited", 0, "QUOTA_EXCEEDED", "Daily quota units exceeded.")
            return _err("QUOTA_EXCEEDED", "Daily quota units exceeded.", request_id=req_id)
        if api_key_row.get("status") == "revoked":
            _finalize("failed", 0, "UNAUTHORIZED", "API key is revoked.")
            return _err("UNAUTHORIZED", "API key is revoked.", request_id=req_id)
    else:
        est_units = 100

    videos = _load("videos.json")
    by_yid = {v.get("youtube_video_id"): v for v in videos if isinstance(v, dict) and v.get("youtube_video_id")}

    def _stale(v):
        if refresh:
            return True
        if max_age_seconds is None:
            return False
        lr = _dt(v.get("last_refreshed_at"))
        if lr is None:
            return True
        return (now - lr).total_seconds() > max_age_seconds

    # upsert seed
    fetched_any = False
    seed_row = by_yid.get(video_id)
    if seed_row is None:
        fetched_any = True
        seed_row = {
            "id": _gen_id("vid"),
            "youtube_video_id": video_id,
            "channel_id": None,
            "youtube_channel_id": None,
            "title": None,
            "description": None,
            "published_at": None,
            "duration_seconds": None,
            "default_language": language,
            "category_id": None,
            "region_restriction": None,
            "status": "active",
            "last_refreshed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        videos.append(seed_row)
        by_yid[video_id] = seed_row
    elif _stale(seed_row):
        fetched_any = True
        seed_row["last_refreshed_at"] = _iso(now)
        seed_row["updated_at"] = _iso(now)

    # generate deterministic related list
    seed = int(hashlib.sha256((video_id + "|" + (region_code or "") + "|" + (language or "")).encode("utf-8")).hexdigest()[:8], 16)
    rng = random.Random(seed)
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-"
    related_ids = []
    for _ in range(100):
        yvid = "".join(rng.choice(alphabet) for _ in range(11))
        if yvid == video_id:
            continue
        related_ids.append(yvid)

    page_ids = related_ids[offset: offset + limit]
    has_more = offset + limit < len(related_ids)
    next_cursor = _b64e({"seed": video_id, "offset": offset + limit}) if has_more else None

    # upsert related video rows
    for yvid in page_ids:
        row = by_yid.get(yvid)
        if row is None:
            fetched_any = True
            pub_dt = now - datetime.timedelta(days=rng.randint(0, 3650))
            row = {
                "id": _gen_id("vid"),
                "youtube_video_id": yvid,
                "channel_id": None,
                "youtube_channel_id": None,
                "title": f"Related to {video_id}",
                "description": None,
                "published_at": _iso(pub_dt),
                "duration_seconds": None,
                "default_language": language,
                "category_id": None,
                "region_restriction": None,
                "status": "active",
                "last_refreshed_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            videos.append(row)
            by_yid[yvid] = row
        else:
            if _stale(row):
                fetched_any = True
                row["last_refreshed_at"] = _iso(now)
                row["updated_at"] = _iso(now)

    _save("videos.json", videos)
    _finalize("fetched_from_youtube" if fetched_any else "served_from_cache", est_units)

    items = [by_yid[yvid] for yvid in page_ids if yvid in by_yid]
    return {
        "request_id": req_id,
        "seed_video": seed_row,
        "items": items,
        "meta": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def getChannelStatistics(channel_ids, refresh=None, max_age_seconds=None, **_extra):
    import json, os, datetime, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getChannelStatistics"
    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _parse_row_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            dt = _parse_dt(v)
        else:
            return None
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{''.join(random.choice(string.ascii_lowercase+string.digits) for _ in range(10))}"

    def _start_of_utc_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _normalize_input():
        return {
            "channel_ids": list(channel_ids) if isinstance(channel_ids, list) else channel_ids,
            "refresh": bool(refresh) if refresh is not None else False,
            "max_age_seconds": max_age_seconds,
        }

    # -------- validation (RELAXED: accept internal channel ids too) --------
    if not isinstance(channel_ids, list) or len(channel_ids) < 1:
        return _err("VALIDATION_ERROR", "channel_ids must be a non-empty array.", field="channel_ids")
    if any(not isinstance(c, str) or not c.strip() for c in channel_ids):
        return _err("VALIDATION_ERROR", "channel_ids must contain non-empty strings.", field="channel_ids")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")
    if max_age_seconds is not None and (not isinstance(max_age_seconds, int) or max_age_seconds < 0):
        return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.", field="max_age_seconds")

    refresh = bool(refresh) if refresh is not None else False
    max_age_seconds = max_age_seconds if max_age_seconds is not None else 24 * 3600

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    channels = _load("channels.json")
    videos = _load("videos.json")
    video_metrics = _load("video_metrics.json")

    # ---- Auth resolution (ambient) ----
    def _count_last_minute(key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_row_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                c += 1
        return c

    def _quota_used_today(key_id):
        sod = _start_of_utc_day(now)
        total = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_row_dt(r.get("created_at"))
            if ts and ts >= sod:
                try:
                    total += int(r.get("youtube_quota_units_charged") or 0)
                except Exception:
                    total += 0
        return total

    def _resolve_key_for_attempt():
        candidates = []
        for k in api_keys:
            if k.get("status") not in ("active", "suspended"):
                continue
            dql = k.get("daily_quota_units")
            rlm = k.get("per_minute_request_limit")
            if not isinstance(dql, int) or dql < 0:
                continue
            if not isinstance(rlm, int) or rlm < 0:
                continue
            candidates.append(k)
        candidates.sort(key=lambda x: (0 if x.get("status") == "active" else 1, -(x.get("daily_quota_units") or 0), -(x.get("per_minute_request_limit") or 0)))
        for k in candidates:
            if (k.get("per_minute_request_limit") or 0) == 0:
                continue
            if _count_last_minute(k["id"]) >= k["per_minute_request_limit"]:
                continue
            if _quota_used_today(k["id"]) >= k["daily_quota_units"]:
                continue
            return k
        return None

    api_key = _resolve_key_for_attempt()
    api_key_id = api_key.get("id") if api_key else None

    # request log: received
    req_id = _gen_id("ytdreq")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "input": _normalize_input(),
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    request_logs.append(req_row)
    _save("request_logs.json", request_logs)

    if api_key is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "No eligible API key available to serve the request."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "No eligible API key available to serve the request.")

    if _count_last_minute(api_key_id) > api_key["per_minute_request_limit"]:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "PER_MINUTE_LIMIT_EXCEEDED"
        req_row["error_message"] = "Per-minute request limit exceeded for this API key."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Per-minute request limit exceeded for this API key.", api_key_id=api_key_id)

    if _quota_used_today(api_key_id) >= api_key["daily_quota_units"]:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
        req_row["error_message"] = "Daily YouTube quota exhausted for this API key; request not executed."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily YouTube quota exhausted for this API key; request not executed.", api_key_id=api_key_id)

    if api_key.get("status") == "revoked":
        req_row["status"] = "failed"
        req_row["error_code"] = "KEY_REVOKED"
        req_row["error_message"] = "API key is revoked."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked.", api_key_id=api_key_id)

    # ---- Resolve channels by youtube_channel_id OR internal id ----
    by_internal = {c.get("id"): c for c in channels if isinstance(c, dict) and c.get("id")}
    by_youtube = {c.get("youtube_channel_id"): c for c in channels if isinstance(c, dict) and c.get("youtube_channel_id")}

    def _is_stale(crow):
        if refresh:
            return True
        lr = _parse_row_dt(crow.get("last_refreshed_at"))
        if lr is None:
            return True
        return (now - lr).total_seconds() > max_age_seconds

    any_mutation = False
    fetched = False

    def _refresh_channel(crow):
        nonlocal any_mutation, fetched
        fetched = True
        now2 = datetime.datetime.now(datetime.timezone.utc)
        crow["status"] = crow.get("status") if crow.get("status") in ("active", "unavailable", "deleted") else "active"
        crow["last_refreshed_at"] = _iso(now2)
        crow["updated_at"] = _iso(now2)
        if not crow.get("created_at"):
            crow["created_at"] = _iso(now2)
        any_mutation = True

    # derive stats best-effort from associated videos + latest metrics
    def _derive_stats_for_channel(crow):
        ch_internal_id = crow.get("id")
        ch_youtube_id = crow.get("youtube_channel_id")
        vids = []
        for v in videos:
            if v.get("channel_id") == ch_internal_id:
                vids.append(v)
            elif ch_youtube_id and v.get("youtube_channel_id") == ch_youtube_id:
                vids.append(v)
        # latest metrics per video
        latest_by_video = {}
        for m in video_metrics:
            vid = m.get("video_id")
            if not vid:
                continue
            sd = _parse_row_dt(m.get("snapshot_at"))
            if sd is None:
                continue
            prev = latest_by_video.get(vid)
            if prev is None or (_parse_row_dt(prev.get("snapshot_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) < sd:
                latest_by_video[vid] = m
        total_views = 0
        any_views = False
        for v in vids:
            lm = latest_by_video.get(v.get("id"))
            if lm and isinstance(lm.get("view_count"), int):
                total_views += lm["view_count"]
                any_views = True
        return {
            "subscriber_count": None,
            "view_count": total_views if any_views else None,
            "video_count": len(vids),
        }

    results = []
    for input_id in channel_ids:
        input_id = input_id.strip()
        crow = by_youtube.get(input_id) or by_internal.get(input_id)
        if crow is None:
            results.append({
                "input_id": input_id,
                "found": False,
                "channel": None,
                "statistics": None,
                "error": {"code": "NOT_FOUND", "message": "Channel not found in cache."}
            })
            continue
        if _is_stale(crow):
            _refresh_channel(crow)
        stats = _derive_stats_for_channel(crow)
        results.append({
            "input_id": input_id,
            "found": True,
            "channel": crow,
            "statistics": stats
        })

    if any_mutation:
        _save("channels.json", channels)

    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", api_keys)

    req_row["status"] = "fetched_from_youtube" if fetched else "served_from_cache"
    req_row["youtube_quota_units_charged"] = int(len(channel_ids))
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("request_logs.json", request_logs)

    return {
        "request_id": req_id,
        "tool_name": tool_name,
        "status": req_row["status"],
        "results": results,
        "meta": {
            "count": len(results),
            "quota_units_charged": req_row["youtube_quota_units_charged"],
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def getChannelTopVideos(channel_id, limit=None, order_by=None, published_after=None, published_before=None, refresh=None, max_age_seconds=None, **_extra):
    import json, os, datetime, re, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # validate
    if not isinstance(channel_id, str) or not re.match(r"^UC[0-9A-Za-z_-]{20,}$", channel_id):
        return _err("VALIDATION_ERROR", "Invalid channel_id.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 50:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.")
    limit = limit if limit is not None else 10
    if order_by is not None and order_by != "view_count":
        return _err("VALIDATION_ERROR", "order_by must be 'view_count'.")
    order_by = order_by or "view_count"
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.")
    refresh = bool(refresh) if refresh is not None else False
    if max_age_seconds is not None:
        if not isinstance(max_age_seconds, int) or max_age_seconds < 0:
            return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.")
    max_age_seconds = max_age_seconds if max_age_seconds is not None else 24 * 3600

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    pa = _parse_dt(published_after) if published_after is not None else None
    pb = _parse_dt(published_before) if published_before is not None else None
    if published_after is not None and pa is None:
        return _err("VALIDATION_ERROR", "published_after must be an RFC3339 date-time string.")
    if published_before is not None and pb is None:
        return _err("VALIDATION_ERROR", "published_before must be an RFC3339 date-time string.")
    if pa and pa.tzinfo is None: pa = pa.replace(tzinfo=datetime.timezone.utc)
    if pb and pb.tzinfo is None: pb = pb.replace(tzinfo=datetime.timezone.utc)
    if pa and pb and pa > pb:
        return _err("VALIDATION_ERROR", "published_after must be <= published_before.")

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    channels = _load("channels.json")
    videos = _load("videos.json")
    video_metrics = _load("video_metrics.json")

    def _start_of_utc_day(dt):
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _quota_used_today(key_id):
        sod = _start_of_utc_day(now)
        total = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            created = _parse_dt(r.get("created_at")) or now
            if created.tzinfo is None:
                created = created.replace(tzinfo=datetime.timezone.utc)
            if created >= sod:
                total += int(r.get("youtube_quota_units_charged") or 0)
        return total

    def _count_last_minute(key_id):
        ws = now - datetime.timedelta(seconds=60)
        c = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            created = _parse_dt(r.get("created_at")) or now
            if created.tzinfo is None:
                created = created.replace(tzinfo=datetime.timezone.utc)
            if created >= ws:
                c += 1
        return c

    def _make_log_id():
        return "rl_" + uuid.uuid4().hex

    # estimate quota: top videos likely requires metrics reads; scale by limit
    est_quota = max(1, min(20, 1 + limit // 5))

    usable_key = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        per_min = int(k.get("per_minute_request_limit") or 0)
        daily = int(k.get("daily_quota_units") or 0)
        if per_min == 0 or daily == 0:
            continue
        if _count_last_minute(k["id"]) >= per_min:
            continue
        if _quota_used_today(k["id"]) + est_quota > daily:
            continue
        usable_key = k
        break
    log_key = usable_key or (api_keys[0] if api_keys else None)

    log_row = {
        "id": _make_log_id(),
        "api_key_id": log_key.get("id") if isinstance(log_key, dict) else None,
        "tool_name": "getChannelTopVideos",
        "input": {
            "channel_id": channel_id, "limit": limit, "order_by": order_by,
            "published_after": published_after, "published_before": published_before,
            "refresh": refresh, "max_age_seconds": max_age_seconds
        },
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    request_logs.append(log_row)
    _save("request_logs.json", request_logs)

    if isinstance(log_key, dict) and log_key.get("status") == "revoked":
        log_row["status"] = "failed"
        log_row["error_code"] = "API_KEY_REVOKED"
        log_row["error_message"] = "API key is revoked."
        log_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked.")

    if usable_key is None:
        log_row["status"] = "rate_limited"
        log_row["error_code"] = "RATE_LIMIT"
        log_row["error_message"] = "Rate limit or quota exceeded."
        log_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit or quota exceeded.")

    def _is_stale(dt_str):
        dt = _parse_dt(dt_str)
        if dt is None:
            return True
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (now - dt).total_seconds() > max_age_seconds

    # ensure channel exists/upsert and optionally refresh
    ch = None
    for c in channels:
        if c.get("youtube_channel_id") == channel_id:
            ch = c
            break
    refreshed_any = False
    if ch is None:
        ch_id = "ch_" + hashlib.sha1(channel_id.encode("utf-8")).hexdigest()[:16]
        existing_ids = {c.get("id") for c in channels}
        if ch_id in existing_ids:
            ch_id = "ch_" + uuid.uuid4().hex
        ch = {
            "id": ch_id,
            "youtube_channel_id": channel_id,
            "title": None, "description": None, "custom_url": None, "country": None, "published_at": None,
            "status": "active",
            "last_refreshed_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        channels.append(ch)
        refreshed_any = True
    else:
        if refresh or _is_stale(ch.get("last_refreshed_at")):
            # cannot transition deleted -> active; keep status as-is, just timestamp refresh
            ch["last_refreshed_at"] = now_iso
            ch["updated_at"] = now_iso
            refreshed_any = True

    # gather channel videos
    ch_vids = []
    for v in videos:
        if v.get("channel_id") == ch.get("id") or v.get("youtube_channel_id") == channel_id:
            if v.get("status") != "deleted":
                ch_vids.append(v)

    # apply publish window
    def _published_ok(v):
        p = _parse_dt(v.get("published_at"))
        if p is None:
            return True  # unknown publish date: keep best-effort
        if p.tzinfo is None:
            p = p.replace(tzinfo=datetime.timezone.utc)
        if pa and p < pa:
            return False
        if pb and p > pb:
            return False
        return True

    ch_vids = [v for v in ch_vids if _published_ok(v)]

    # ensure metrics freshness for ranking when requested
    # offline: if missing/stale, append computed_from_cache snapshot based on existing latest (or zeros)
    def _latest_metric_for_video(vid_internal):
        best = None
        for m in video_metrics:
            if m.get("video_id") != vid_internal:
                continue
            sat = _parse_dt(m.get("snapshot_at"))
            if sat is None:
                continue
            if best is None or sat > best[0]:
                best = (sat, m)
        return best[1] if best else None

    def _append_metric(vid_internal, base):
        snap_id = "vm_" + uuid.uuid4().hex
        vc = base.get("view_count") if base else 0
        lc = base.get("like_count") if base else 0
        cc = base.get("comment_count") if base else 0
        vc = int(vc or 0); lc = int(lc or 0); cc = int(cc or 0)
        er = (lc + cc) / max(vc, 1)
        row = {
            "id": snap_id,
            "video_id": vid_internal,
            "snapshot_at": now_iso,
            "view_count": vc,
            "like_count": lc,
            "comment_count": cc,
            "favorite_count": int((base or {}).get("favorite_count") or 0),
            "engagement_ratio": er,
            "source": "computed_from_cache",
            "created_at": now_iso,
            "updated_at": now_iso
        }
        # enforce unique(video_id, snapshot_at): if exists, idempotently skip
        for m in video_metrics:
            if m.get("video_id") == vid_internal and m.get("snapshot_at") == now_iso:
                return False
        video_metrics.append(row)
        return True

    metrics_refreshed = False
    if refresh:
        for v in ch_vids:
            vid_internal = v.get("id")
            if not vid_internal:
                continue
            base = _latest_metric_for_video(vid_internal)
            if _append_metric(vid_internal, base):
                metrics_refreshed = True
    else:
        for v in ch_vids:
            vid_internal = v.get("id")
            if not vid_internal:
                continue
            lm = _latest_metric_for_video(vid_internal)
            sat = _parse_dt(lm.get("snapshot_at")) if lm else None
            stale = True
            if sat:
                if sat.tzinfo is None:
                    sat = sat.replace(tzinfo=datetime.timezone.utc)
                stale = (now - sat).total_seconds() > max_age_seconds
            if lm is None or stale:
                if _append_metric(vid_internal, lm):
                    metrics_refreshed = True

    if metrics_refreshed:
        _save("video_metrics.json", video_metrics)

    # rank
    ranked = []
    for v in ch_vids:
        vid_internal = v.get("id")
        lm = _latest_metric_for_video(vid_internal) if vid_internal else None
        view_count = int(lm.get("view_count") or 0) if lm else 0
        ranked.append((view_count, v, lm))
    ranked.sort(key=lambda x: (x[0], _parse_dt(x[1].get("published_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    items = []
    for vc, v, lm in ranked[:limit]:
        items.append({
            "video": v,
            "latest_metrics": lm,
            "rank_value": vc
        })

    _save("channels.json", channels)

    log_row["youtube_quota_units_charged"] = est_quota
    log_row["status"] = "fetched_from_youtube" if (refreshed_any or metrics_refreshed) else "served_from_cache"
    log_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    usable_key["last_used_at"] = log_row["updated_at"]
    usable_key["updated_at"] = log_row["updated_at"]
    _save("api_keys.json", api_keys)
    _save("request_logs.json", request_logs)

    return {
        "tool_name": "getChannelTopVideos",
        "channel": ch,
        "items": items,
        "meta": {
            "limit": limit,
            "returned": len(items),
            "refreshed_any": bool(refreshed_any),
            "metrics_refreshed": bool(metrics_refreshed),
            "quota_units_charged": est_quota,
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def getVideoEngagementRatio(video_ids, refresh=None, max_age_seconds=None, snapshot_at=None, **_extra):
    import json, os, datetime, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "getVideoEngagementRatio"
    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _parse_row_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            dt = _parse_dt(v)
        else:
            return None
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{''.join(random.choice(string.ascii_lowercase+string.digits) for _ in range(10))}"

    def _start_of_utc_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _normalize_input():
        return {
            "video_ids": list(video_ids) if isinstance(video_ids, list) else video_ids,
            "refresh": bool(refresh) if refresh is not None else False,
            "max_age_seconds": max_age_seconds,
            "snapshot_at": snapshot_at,
        }

    # validation (RELAXED)
    if not isinstance(video_ids, list) or len(video_ids) < 1:
        return _err("VALIDATION_ERROR", "video_ids must be a non-empty array.", field="video_ids")
    if any(not isinstance(v, str) or not v.strip() for v in video_ids):
        return _err("VALIDATION_ERROR", "video_ids must contain non-empty strings.", field="video_ids")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")
    if max_age_seconds is not None and (not isinstance(max_age_seconds, int) or max_age_seconds < 0):
        return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.", field="max_age_seconds")
    snap_target = _parse_dt(snapshot_at) if snapshot_at is not None else None
    if snapshot_at is not None and snap_target is None:
        return _err("VALIDATION_ERROR", "snapshot_at must be an RFC3339 date-time string.", field="snapshot_at")

    refresh = bool(refresh) if refresh is not None else False
    max_age_seconds = max_age_seconds if max_age_seconds is not None else 24 * 3600

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    videos = _load("videos.json")
    video_metrics = _load("video_metrics.json")

    # auth resolution
    def _count_last_minute(key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_row_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                c += 1
        return c

    def _quota_used_today(key_id):
        sod = _start_of_utc_day(now)
        total = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            ts = _parse_row_dt(r.get("created_at"))
            if ts and ts >= sod:
                try:
                    total += int(r.get("youtube_quota_units_charged") or 0)
                except Exception:
                    total += 0
        return total

    def _resolve_key_for_attempt():
        candidates = []
        for k in api_keys:
            if k.get("status") not in ("active", "suspended"):
                continue
            dql = k.get("daily_quota_units")
            rlm = k.get("per_minute_request_limit")
            if not isinstance(dql, int) or dql < 0:
                continue
            if not isinstance(rlm, int) or rlm < 0:
                continue
            candidates.append(k)
        candidates.sort(key=lambda x: (0 if x.get("status") == "active" else 1, -(x.get("daily_quota_units") or 0), -(x.get("per_minute_request_limit") or 0)))
        for k in candidates:
            if (k.get("per_minute_request_limit") or 0) == 0:
                continue
            if _count_last_minute(k["id"]) >= k["per_minute_request_limit"]:
                continue
            if _quota_used_today(k["id"]) >= k["daily_quota_units"]:
                continue
            return k
        return None

    api_key = _resolve_key_for_attempt()
    api_key_id = api_key.get("id") if api_key else None

    # request log: received
    req_id = _gen_id("ytdreq")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "input": _normalize_input(),
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    request_logs.append(req_row)
    _save("request_logs.json", request_logs)

    if api_key is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "No eligible API key available to serve the request."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "No eligible API key available to serve the request.")

    if _count_last_minute(api_key_id) > api_key["per_minute_request_limit"]:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "PER_MINUTE_LIMIT_EXCEEDED"
        req_row["error_message"] = "Per-minute request limit exceeded for this API key."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Per-minute request limit exceeded for this API key.", api_key_id=api_key_id)

    if _quota_used_today(api_key_id) >= api_key["daily_quota_units"]:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
        req_row["error_message"] = "Daily YouTube quota exhausted for this API key; request not executed."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily YouTube quota exhausted for this API key; request not executed.", api_key_id=api_key_id)

    if api_key.get("status") == "revoked":
        req_row["status"] = "failed"
        req_row["error_code"] = "KEY_REVOKED"
        req_row["error_message"] = "API key is revoked."
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked.", api_key_id=api_key_id)

    by_internal = {v.get("id"): v for v in videos if isinstance(v, dict) and v.get("id")}
    by_youtube = {v.get("youtube_video_id"): v for v in videos if isinstance(v, dict) and v.get("youtube_video_id")}

    def _metric_dt(m):
        return _parse_row_dt(m.get("snapshot_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    def _closest_metric(internal_vid):
        cands = [m for m in video_metrics if m.get("video_id") == internal_vid]
        if not cands:
            return None
        if snap_target is None:
            return max(cands, key=_metric_dt)
        best = None
        best_diff = None
        for m in cands:
            d = _metric_dt(m)
            diff = abs((d - snap_target).total_seconds())
            if best is None or diff < best_diff:
                best = m
                best_diff = diff
        return best

    def _is_metric_stale(m):
        if refresh:
            return True
        if m is None:
            return True
        sd = _parse_row_dt(m.get("snapshot_at"))
        if sd is None:
            return True
        return (now - sd).total_seconds() > max_age_seconds

    any_mutation = False
    fetched = False

    def _append_fresh_metric(video_internal_id):
        nonlocal any_mutation, fetched
        fetched = True
        now2 = datetime.datetime.now(datetime.timezone.utc)
        met = {
            "id": _gen_id("ytmet"),
            "video_id": video_internal_id,
            "snapshot_at": _iso(now2),
            "view_count": None,
            "like_count": None,
            "comment_count": None,
            "favorite_count": None,
            "engagement_ratio": None,
            "source": "youtube_api",
            "created_at": _iso(now2),
            "updated_at": _iso(now2),
        }
        # unique(video_id, snapshot_at)
        if not any((x.get("video_id") == video_internal_id and x.get("snapshot_at") == met["snapshot_at"]) for x in video_metrics):
            video_metrics.append(met)
            any_mutation = True
        return met

    results = []
    for input_id in video_ids:
        input_id = input_id.strip()
        vrow = by_youtube.get(input_id) or by_internal.get(input_id)
        if vrow is None:
            results.append({
                "input_id": input_id,
                "found": False,
                "video": None,
                "metrics": None,
                "engagement_ratio": None,
                "error": {"code": "NOT_FOUND", "message": "Video not found in cache."}
            })
            continue

        met = _closest_metric(vrow["id"])
        if _is_metric_stale(met):
            met = _append_fresh_metric(vrow["id"])

        # compute ratio if possible
        views = met.get("view_count")
        likes = met.get("like_count")
        comments = met.get("comment_count")
        ratio = None
        if isinstance(views, int) and views >= 0:
            denom = max(views, 1)
            num = (likes if isinstance(likes, int) and likes >= 0 else 0) + (comments if isinstance(comments, int) and comments >= 0 else 0)
            ratio = float(num) / float(denom)
        met_out = dict(met)
        if ratio is not None:
            met_out["engagement_ratio"] = ratio
        results.append({
            "input_id": input_id,
            "found": True,
            "video": vrow,
            "metrics": met_out,
            "engagement_ratio": ratio
        })

    if any_mutation:
        _save("video_metrics.json", video_metrics)

    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", api_keys)

    req_row["status"] = "fetched_from_youtube" if fetched else "served_from_cache"
    req_row["youtube_quota_units_charged"] = int(len(video_ids))
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("request_logs.json", request_logs)

    return {
        "request_id": req_id,
        "tool_name": tool_name,
        "status": req_row["status"],
        "results": results,
        "meta": {
            "count": len(results),
            "quota_units_charged": req_row["youtube_quota_units_charged"],
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def getTrendingVideos(region_code, category_id=None, limit=None, cursor=None, refresh=None, max_age_seconds=None, **_extra):
    import json, os, datetime, re, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # validate
    if not isinstance(region_code, str) or len(region_code) != 2:
        return _err("VALIDATION_ERROR", "region_code must be a 2-letter code.")
    if not re.match(r"^[A-Za-z]{2}$", region_code):
        return _err("VALIDATION_ERROR", "region_code must contain only letters.")
    region_code = region_code.upper()

    allowed_categories = {1, 2, 10, 15, 17, 18, 19, 20, 21}
    if category_id is not None:
        if not isinstance(category_id, int) or category_id not in allowed_categories:
            return _err("VALIDATION_ERROR", "category_id must be one of the supported category IDs.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 50:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.")
    limit = limit if limit is not None else 10
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.")
    refresh = bool(refresh) if refresh is not None else False
    if max_age_seconds is not None:
        if not isinstance(max_age_seconds, int) or max_age_seconds < 0:
            return _err("VALIDATION_ERROR", "max_age_seconds must be an integer >= 0.")
    max_age_seconds = max_age_seconds if max_age_seconds is not None else 24 * 3600

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    videos = _load("videos.json")
    video_metrics = _load("video_metrics.json")

    def _start_of_utc_day(dt):
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _quota_used_today(key_id):
        sod = _start_of_utc_day(now)
        total = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            created = _parse_dt(r.get("created_at")) or now
            if created.tzinfo is None:
                created = created.replace(tzinfo=datetime.timezone.utc)
            if created >= sod:
                total += int(r.get("youtube_quota_units_charged") or 0)
        return total

    def _count_last_minute(key_id):
        ws = now - datetime.timedelta(seconds=60)
        c = 0
        for r in request_logs:
            if r.get("api_key_id") != key_id:
                continue
            created = _parse_dt(r.get("created_at")) or now
            if created.tzinfo is None:
                created = created.replace(tzinfo=datetime.timezone.utc)
            if created >= ws:
                c += 1
        return c

    def _make_log_id():
        return "rl_" + uuid.uuid4().hex

    est_quota = max(1, min(25, 2 + limit // 4))

    usable_key = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        per_min = int(k.get("per_minute_request_limit") or 0)
        daily = int(k.get("daily_quota_units") or 0)
        if per_min == 0 or daily == 0:
            continue
        if _count_last_minute(k["id"]) >= per_min:
            continue
        if _quota_used_today(k["id"]) + est_quota > daily:
            continue
        usable_key = k
        break
    log_key = usable_key or (api_keys[0] if api_keys else None)

    log_row = {
        "id": _make_log_id(),
        "api_key_id": log_key.get("id") if isinstance(log_key, dict) else None,
        "tool_name": "getTrendingVideos",
        "input": {"region_code": region_code, "category_id": category_id, "limit": limit, "cursor": cursor, "refresh": refresh, "max_age_seconds": max_age_seconds},
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    request_logs.append(log_row)
    _save("request_logs.json", request_logs)

    if isinstance(log_key, dict) and log_key.get("status") == "revoked":
        log_row["status"] = "failed"
        log_row["error_code"] = "API_KEY_REVOKED"
        log_row["error_message"] = "API key is revoked."
        log_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked.")

    if usable_key is None:
        log_row["status"] = "rate_limited"
        log_row["error_code"] = "RATE_LIMIT"
        log_row["error_message"] = "Rate limit or quota exceeded."
        log_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit or quota exceeded.")

    def _is_stale(dt_str):
        dt = _parse_dt(dt_str)
        if dt is None:
            return True
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (now - dt).total_seconds() > max_age_seconds

    # cursor decoding (opaque): base16 offset
    offset = 0
    if cursor:
        try:
            if cursor.startswith("off_"):
                offset = int(cursor.split("_", 1)[1])
            else:
                offset = int(cursor)
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Filter candidates by region/category and availability
    def _region_allowed(v):
        rr = v.get("region_restriction")
        if not isinstance(rr, dict):
            return True
        allowed = rr.get("allowed")
        blocked = rr.get("blocked")
        if isinstance(allowed, list) and len(allowed) > 0:
            return region_code in [str(x).upper() for x in allowed if isinstance(x, str)]
        if isinstance(blocked, list) and len(blocked) > 0:
            return region_code not in [str(x).upper() for x in blocked if isinstance(x, str)]
        return True

    candidates = []
    for v in videos:
        if v.get("status") != "active":
            continue
        if category_id is not None and v.get("category_id") != category_id:
            continue
        if not _region_allowed(v):
            continue
        candidates.append(v)

    # Trending ordering: newest available metrics snapshot; else metadata recency
    def _latest_metric_for_video(vid_internal):
        best = None
        for m in video_metrics:
            if m.get("video_id") != vid_internal:
                continue
            sat = _parse_dt(m.get("snapshot_at"))
            if sat is None:
                continue
            if sat.tzinfo is None:
                sat = sat.replace(tzinfo=datetime.timezone.utc)
            if best is None or sat > best[0]:
                best = (sat, m)
        return best

    # refresh: if enabled, ensure each page's candidates have a fresh metric snapshot (computed_from_cache)
    refreshed_any = False
    if refresh:
        for v in candidates:
            lm = _latest_metric_for_video(v.get("id"))
            if lm is None or _is_stale((lm[1] or {}).get("snapshot_at")):
                # append computed snapshot using last metric values or zeros
                base = lm[1] if lm else None
                vc = int((base or {}).get("view_count") or 0)
                lc = int((base or {}).get("like_count") or 0)
                cc = int((base or {}).get("comment_count") or 0)
                er = (lc + cc) / max(vc, 1)
                # unique(video_id, snapshot_at)
                exists = False
                for m in video_metrics:
                    if m.get("video_id") == v.get("id") and m.get("snapshot_at") == now_iso:
                        exists = True
                        break
                if not exists and v.get("id"):
                    video_metrics.append({
                        "id": "vm_" + uuid.uuid4().hex,
                        "video_id": v.get("id"),
                        "snapshot_at": now_iso,
                        "view_count": vc,
                        "like_count": lc,
                        "comment_count": cc,
                        "favorite_count": int((base or {}).get("favorite_count") or 0),
                        "engagement_ratio": er,
                        "source": "computed_from_cache",
                        "created_at": now_iso,
                        "updated_at": now_iso
                    })
                    refreshed_any = True
        if refreshed_any:
            _save("video_metrics.json", video_metrics)

    scored = []
    for v in candidates:
        lm = _latest_metric_for_video(v.get("id"))
        if lm:
            sat, row = lm
            score_primary = sat.timestamp()
            score_secondary = int(row.get("view_count") or 0)
        else:
            pub = _parse_dt(v.get("published_at"))
            if pub and pub.tzinfo is None:
                pub = pub.replace(tzinfo=datetime.timezone.utc)
            score_primary = (pub.timestamp() if pub else 0.0)
            score_secondary = 0
        scored.append((score_primary, score_secondary, v, lm[1] if lm else None))
    scored.sort(key=lambda x: (x[0], x[1]), reverse=True)

    page = scored[offset: offset + limit]
    items = []
    for _, __, v, lmrow in page:
        items.append({"video": v, "latest_metrics": lmrow})

    next_offset = offset + len(page)
    has_more = next_offset < len(scored)
    next_cursor = f"off_{next_offset}" if has_more else None

    log_row["youtube_quota_units_charged"] = est_quota
    log_row["status"] = "fetched_from_youtube" if refreshed_any else "served_from_cache"
    log_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    usable_key["last_used_at"] = log_row["updated_at"]
    usable_key["updated_at"] = log_row["updated_at"]
    _save("api_keys.json", api_keys)
    _save("request_logs.json", request_logs)

    return {
        "tool_name": "getTrendingVideos",
        "region_code": region_code,
        "category_id": category_id,
        "items": items,
        "cursor": next_cursor,
        "meta": {
            "limit": limit,
            "offset": offset,
            "returned": len(items),
            "total_candidates": len(scored),
            "has_more": bool(has_more),
            "refreshed_any": bool(refreshed_any),
            "quota_units_charged": est_quota,
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def compareVideos(video_ids, include_transcript=None, freshness_max_age_seconds=None, snapshot_at=None, metrics_source=None, **_extra):
    import json, os, datetime, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "compareVideos"
    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str):
            ss = s.strip()
            if not ss:
                return None
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _parse_row_dt(v):
        return _parse_dt(v)

    def _gen_id(prefix):
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{''.join(random.choice(string.ascii_lowercase+string.digits) for _ in range(10))}"

    def _start_of_utc_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _find_api_key_context():
        # Ambient auth: choose ANY key that can serve requests (active preferred),
        # and that has non-negative quotas/limits.
        keys = _load("api_keys.json") or []
        if not isinstance(keys, list):
            keys = []
        def _ok_row(k):
            if not isinstance(k, dict):
                return False
            if k.get("id") is None:
                return False
            if k.get("status") not in ("active", "suspended", "revoked"):
                return False
            dq = k.get("daily_quota_units")
            pm = k.get("per_minute_request_limit")
            if not isinstance(dq, int) or dq < 0:
                return False
            if not isinstance(pm, int) or pm < 0:
                return False
            return True

        candidates = [k for k in keys if _ok_row(k)]
        if not candidates:
            return None

        # Prefer active, then suspended, then revoked (revoked cannot succeed but can still log failures/rate_limited)
        status_rank = {"active": 0, "suspended": 1, "revoked": 2}
        candidates.sort(key=lambda r: (status_rank.get(r.get("status"), 9), r.get("id")))
        return candidates[0]

    def _count_requests_last_minute(logs, api_key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ca = _parse_row_dt(r.get("created_at"))
            if ca and ca >= cutoff:
                c += 1
        return c

    def _sum_quota_today(logs, api_key_id):
        start = _start_of_utc_day(now)
        total = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ca = _parse_row_dt(r.get("created_at"))
            if ca and ca >= start:
                u = r.get("youtube_quota_units_charged")
                if isinstance(u, int) and u >= 0:
                    total += u
        return total

    def _select_video_metrics(metrics_rows, video_internal_id, desired_snapshot_at, prefer_source):
        # Choose snapshot closest to desired_snapshot_at (if provided) else latest.
        # If prefer_source provided, use it as tie-breaker preference among same "distance".
        relevant = []
        for m in metrics_rows:
            if not isinstance(m, dict):
                continue
            if m.get("video_id") != video_internal_id:
                continue
            sa = _parse_row_dt(m.get("snapshot_at"))
            if not sa:
                continue
            relevant.append((m, sa))

        if not relevant:
            return None

        prefer_rank = {"youtube_api": 0, "computed_from_cache": 1, "backfill": 2}
        if prefer_source not in prefer_rank:
            prefer_source = None

        if desired_snapshot_at is None:
            # latest, then prefer source, then id stable
            relevant.sort(key=lambda x: (x[1], -1), reverse=True)
            # among top timestamp, pick preferred source
            top_ts = relevant[0][1]
            same_ts = [x[0] for x in relevant if x[1] == top_ts]
            if prefer_source:
                same_ts.sort(key=lambda r: (prefer_rank.get(r.get("source"), 9), r.get("id") or ""))
            else:
                same_ts.sort(key=lambda r: (r.get("id") or ""))
            return same_ts[0]

        # closest to desired_snapshot_at
        def _dist(sa):
            return abs((sa - desired_snapshot_at).total_seconds())

        # sort by distance then source preference then snapshot recency then id
        relevant.sort(key=lambda x: (_dist(x[1]), prefer_rank.get(x[0].get("source"), 9) if prefer_source else 9, -x[1].timestamp(), x[0].get("id") or ""))
        return relevant[0][0]

    def _upsert_video_by_youtube_id(videos_rows, youtube_video_id):
        # Upsert key: youtube_video_id globally unique.
        for v in videos_rows:
            if isinstance(v, dict) and v.get("youtube_video_id") == youtube_video_id:
                return v, False
        vid = {
            "id": _gen_id("ytvid"),
            "youtube_video_id": youtube_video_id,
            "channel_id": None,
            "youtube_channel_id": None,
            "title": None,
            "description": None,
            "published_at": None,
            "duration_seconds": None,
            "default_language": None,
            "category_id": None,
            "region_restriction": None,
            "status": "active",
            "last_refreshed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        videos_rows.append(vid)
        return vid, True

    def _append_metrics_snapshot(metrics_rows, video_internal_id, source):
        # Create a new snapshot with best-effort synthetic counts (non-negative).
        # The contract says to fetch if stale/missing; offline store can't call YouTube,
        # so we simulate "fetched_from_youtube" by recording a youtube_api snapshot with
        # monotonic-ish counts derived from latest snapshot if present.
        latest = None
        latest_dt = None
        for m in metrics_rows:
            if not isinstance(m, dict):
                continue
            if m.get("video_id") != video_internal_id:
                continue
            sa = _parse_row_dt(m.get("snapshot_at"))
            if sa and (latest_dt is None or sa > latest_dt):
                latest_dt = sa
                latest = m

        def _nn_int(x):
            return x if isinstance(x, int) and x >= 0 else None

        base_views = _nn_int(latest.get("view_count")) if isinstance(latest, dict) else None
        base_likes = _nn_int(latest.get("like_count")) if isinstance(latest, dict) else None
        base_comments = _nn_int(latest.get("comment_count")) if isinstance(latest, dict) else None
        base_fav = _nn_int(latest.get("favorite_count")) if isinstance(latest, dict) else None

        # light deterministic-ish increments
        inc = int(now.timestamp()) % 97
        view = (base_views if base_views is not None else 0) + inc
        like = (base_likes if base_likes is not None else 0) + (inc // 4)
        comment = (base_comments if base_comments is not None else 0) + (inc // 9)
        fav = (base_fav if base_fav is not None else 0)

        denom = view if view > 0 else 1
        ratio = (like + comment) / float(denom)

        snap = {
            "id": _gen_id("ytmet"),
            "video_id": video_internal_id,
            "snapshot_at": _iso(now),
            "view_count": view,
            "like_count": like,
            "comment_count": comment,
            "favorite_count": fav,
            "engagement_ratio": ratio if ratio >= 0 else 0.0,
            "source": source,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        # enforce unique(video_id, snapshot_at): if collision, adjust snapshot_at by +1s
        existing = {(m.get("video_id"), m.get("snapshot_at")) for m in metrics_rows if isinstance(m, dict)}
        if (video_internal_id, snap["snapshot_at"]) in existing:
            snap["snapshot_at"] = _iso(now + datetime.timedelta(seconds=1))
        metrics_rows.append(snap)
        return snap

    # -------- Validate inputs (RELAXED) --------
    # Audit defect: the real service must accept even if only 1 id was supplied.
    if not isinstance(video_ids, list):
        # allow caller to pass a single string too
        if isinstance(video_ids, str) and video_ids.strip():
            video_ids = [video_ids.strip()]
        else:
            return _err("VALIDATION_ERROR", "video_ids must be an array of strings.", field="video_ids")
    # accept 1+ items (do not enforce minItems=2)
    cleaned_ids = []
    for i, vid in enumerate(video_ids):
        if not isinstance(vid, str) or not vid.strip():
            return _err("VALIDATION_ERROR", "video_ids must contain only non-empty strings.", field="video_ids", index=i)
        cleaned_ids.append(vid.strip())
    video_ids = cleaned_ids

    if include_transcript is not None and not isinstance(include_transcript, bool):
        return _err("VALIDATION_ERROR", "include_transcript must be a boolean.", field="include_transcript")
    include_transcript = bool(include_transcript) if include_transcript is not None else False

    if freshness_max_age_seconds is not None:
        if not isinstance(freshness_max_age_seconds, int):
            return _err("VALIDATION_ERROR", "freshness_max_age_seconds must be an integer.", field="freshness_max_age_seconds")
        if freshness_max_age_seconds < 0:
            return _err("VALIDATION_ERROR", "freshness_max_age_seconds must be >= 0.", field="freshness_max_age_seconds")

    desired_snapshot_at = None
    if snapshot_at is not None:
        desired_snapshot_at = _parse_dt(snapshot_at)
        if desired_snapshot_at is None:
            return _err("VALIDATION_ERROR", "snapshot_at must be an RFC3339 timestamp.", field="snapshot_at")

    if metrics_source is not None and metrics_source not in ("youtube_api", "computed_from_cache", "backfill"):
        return _err("VALIDATION_ERROR", "metrics_source must be one of: youtube_api, computed_from_cache, backfill.", field="metrics_source")

    # -------- Request logging + auth context + rate/quota enforcement --------
    api_key = _find_api_key_context()
    if api_key is None:
        # Still log attempt without api_key_id? But tool requires ambient auth; if none exist, unauthorized.
        # Record request log as failed with null api_key_id.
        logs = _load("request_logs.json") or []
        if not isinstance(logs, list):
            logs = []
        req_id = _gen_id("ytdreq")
        req = {
            "id": req_id,
            "api_key_id": None,
            "tool_name": tool_name,
            "input": {
                "video_ids": list(video_ids),
                "include_transcript": include_transcript,
                "freshness_max_age_seconds": freshness_max_age_seconds,
                "snapshot_at": snapshot_at,
                "metrics_source": metrics_source,
            },
            "status": "failed",
            "youtube_quota_units_charged": 0,
            "error_code": "UNAUTHORIZED",
            "error_message": "No available API key context could satisfy this request.",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        logs.append(req)
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No available API key context could satisfy this request.")

    logs = _load("request_logs.json") or []
    if not isinstance(logs, list):
        logs = []

    req_id = _gen_id("ytdreq")
    req_row = {
        "id": req_id,
        "api_key_id": api_key.get("id"),
        "tool_name": tool_name,
        "input": {
            "video_ids": list(video_ids),
            "include_transcript": include_transcript,
            "freshness_max_age_seconds": freshness_max_age_seconds,
            "snapshot_at": snapshot_at,
            "metrics_source": metrics_source,
        },
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    logs.append(req_row)
    _save("request_logs.json", logs)

    # Per-minute request limit
    pm_limit = api_key.get("per_minute_request_limit")
    if isinstance(pm_limit, int) and pm_limit >= 0:
        if pm_limit == 0:
            # always rate limited for authenticated usage
            req_row["status"] = "rate_limited"
            req_row["youtube_quota_units_charged"] = 0
            req_row["error_code"] = "PER_MINUTE_LIMIT_EXCEEDED"
            req_row["error_message"] = "Per-minute request limit exceeded for this API key."
            req_row["updated_at"] = _iso(now)
            _save("request_logs.json", logs)
            return _err("RATE_LIMIT", "Per-minute request limit exceeded for this API key.", error_code=req_row["error_code"])
        if _count_requests_last_minute(logs, api_key.get("id")) > pm_limit:
            req_row["status"] = "rate_limited"
            req_row["youtube_quota_units_charged"] = 0
            req_row["error_code"] = "PER_MINUTE_LIMIT_EXCEEDED"
            req_row["error_message"] = "Per-minute request limit exceeded for this API key."
            req_row["updated_at"] = _iso(now)
            _save("request_logs.json", logs)
            return _err("RATE_LIMIT", "Per-minute request limit exceeded for this API key.", error_code=req_row["error_code"])

    # Daily quota check (estimate units for compareVideos)
    estimated_units = max(1, len(video_ids))  # best-effort; at least 1
    dq = api_key.get("daily_quota_units")
    if isinstance(dq, int) and dq >= 0:
        used = _sum_quota_today(logs, api_key.get("id"))
        if used + estimated_units > dq:
            req_row["status"] = "rate_limited"
            req_row["youtube_quota_units_charged"] = 0
            req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
            req_row["error_message"] = "Daily YouTube quota exhausted for this API key; request not executed."
            req_row["updated_at"] = _iso(now)
            _save("request_logs.json", logs)
            return _err("QUOTA_EXCEEDED", "Daily YouTube quota exhausted for this API key; request not executed.", error_code=req_row["error_code"])

    # Revoked keys cannot produce successful terminal status.
    key_status = api_key.get("status")

    # -------- Serve from cache and refresh if needed --------
    videos = _load("videos.json") or []
    if not isinstance(videos, list):
        videos = []
    metrics = _load("video_metrics.json") or []
    if not isinstance(metrics, list):
        metrics = []
    transcripts = _load("video_transcripts.json") or []
    if not isinstance(transcripts, list):
        transcripts = []

    freshness = freshness_max_age_seconds
    refreshed_any = False
    created_any = False
    appended_metrics_any = False

    # Resolve or upsert videos and ensure metrics are available/fresh-ish as requested.
    internal_by_youtube = {}
    for ytid in video_ids:
        vrow, created = _upsert_video_by_youtube_id(videos, ytid)
        internal_by_youtube[ytid] = vrow
        if created:
            created_any = True
            refreshed_any = True
        else:
            # refresh staleness on entity
            if freshness is not None:
                lra = _parse_row_dt(vrow.get("last_refreshed_at"))
                if lra is None or (now - lra).total_seconds() > freshness:
                    vrow["last_refreshed_at"] = _iso(now)
                    vrow["updated_at"] = _iso(now)
                    refreshed_any = True

        # ensure metrics exist/fresh (required by business rule for compareVideos / engagement computations)
        need_snapshot = False
        chosen = _select_video_metrics(metrics, vrow.get("id"), desired_snapshot_at, metrics_source)
        if chosen is None:
            need_snapshot = True
        elif freshness is not None:
            sa = _parse_row_dt(chosen.get("snapshot_at"))
            if sa is None or (now - sa).total_seconds() > freshness:
                need_snapshot = True

        if need_snapshot:
            # create a new snapshot, prefer requested metrics_source if given, else youtube_api
            src = metrics_source if metrics_source in ("youtube_api", "computed_from_cache", "backfill") else "youtube_api"
            _append_metrics_snapshot(metrics, vrow.get("id"), src)
            appended_metrics_any = True

    if created_any or refreshed_any:
        _save("videos.json", videos)
    if appended_metrics_any:
        _save("video_metrics.json", metrics)

    # Build response comparison entries
    comparisons = []
    for ytid in video_ids:
        v = internal_by_youtube.get(ytid)
        if not isinstance(v, dict):
            continue
        vid_internal = v.get("id")

        m = _select_video_metrics(metrics, vid_internal, desired_snapshot_at, metrics_source)
        # In case selection still fails (shouldn't), leave metrics null
        views = m.get("view_count") if isinstance(m, dict) else None
        likes = m.get("like_count") if isinstance(m, dict) else None
        comments = m.get("comment_count") if isinstance(m, dict) else None
        favorites = m.get("favorite_count") if isinstance(m, dict) else None
        ratio = m.get("engagement_ratio") if isinstance(m, dict) else None

        entry = {
            "youtube_video_id": v.get("youtube_video_id"),
            "video": v,
            "metrics": {
                "snapshot_at": m.get("snapshot_at") if isinstance(m, dict) else None,
                "source": m.get("source") if isinstance(m, dict) else None,
                "view_count": views,
                "like_count": likes,
                "comment_count": comments,
                "favorite_count": favorites,
                "engagement_ratio": ratio,
            }
        }

        if include_transcript:
            # transcript availability summary
            has_available = False
            available_langs = set()
            for tx in transcripts:
                if not isinstance(tx, dict):
                    continue
                if tx.get("video_id") != vid_internal:
                    continue
                if tx.get("status") == "available":
                    has_available = True
                    lang = tx.get("language")
                    if isinstance(lang, str) and lang:
                        available_langs.add(lang)
            entry["transcript"] = {
                "has_available": has_available,
                "available_languages": sorted(available_langs),
            }

        comparisons.append(entry)

    # Terminalize request log
    if key_status == "revoked":
        req_row["status"] = "failed"
        req_row["youtube_quota_units_charged"] = 0
        req_row["error_code"] = "API_KEY_REVOKED"
        req_row["error_message"] = "API key is revoked; successful requests are not permitted."
        req_row["updated_at"] = _iso(now)
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "API key is revoked; successful requests are not permitted.", error_code=req_row["error_code"])

    # Consider as fetched_from_youtube if we refreshed anything or appended metrics; else served_from_cache
    req_row["status"] = "fetched_from_youtube" if (refreshed_any or appended_metrics_any) else "served_from_cache"
    req_row["youtube_quota_units_charged"] = estimated_units if req_row["status"] == "fetched_from_youtube" else 0
    req_row["updated_at"] = _iso(now)

    # update key last_used_at only for successful authenticated requests
    api_keys = _load("api_keys.json") or []
    if not isinstance(api_keys, list):
        api_keys = []
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break

    _save("request_logs.json", logs)
    _save("api_keys.json", api_keys)

    # Provide useful summary, keep stable envelope-ish output
    # (no schema specified; return comparison data with metadata)
    latency_ms = int((time.time() - t0) * 1000)
    return {
        "request_id": req_id,
        "tool_name": tool_name,
        "status": req_row["status"],
        "latency_ms": latency_ms,
        "count": len(comparisons),
        "items": comparisons,
    }

def createApiKey(label, owner_type, owner_id, daily_quota_units, per_minute_request_limit, **_extra):
    import json, os, datetime, time, hashlib, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{''.join(random.choice(string.ascii_lowercase+string.digits) for _ in range(10))}"

    # Validate per tool contract (note: schema owner_type differs; map/validate carefully)
    if not isinstance(label, str) or not (1 <= len(label) <= 100):
        return _err("VALIDATION_ERROR", "label must be a non-empty string up to 100 chars")
    if owner_type not in ["user", "project", "service"]:
        return _err("VALIDATION_ERROR", "owner_type must be one of: user, project, service")
    if not isinstance(owner_id, str) or not (1 <= len(owner_id) <= 128):
        return _err("VALIDATION_ERROR", "owner_id must be a non-empty string up to 128 chars")
    if not isinstance(daily_quota_units, int) or daily_quota_units < 0:
        return _err("VALIDATION_ERROR", "daily_quota_units must be an integer >= 0")
    if not isinstance(per_minute_request_limit, int) or per_minute_request_limit < 0:
        return _err("VALIDATION_ERROR", "per_minute_request_limit must be an integer >= 0")

    api_keys = _load("api_keys.json")

    # Generate plaintext key once and store only its hash (key_hash field)
    plain = "yt_" + "".join(random.choice(string.ascii_letters + string.digits) for _ in range(36))
    key_hash = hashlib.sha256(plain.encode("utf-8")).hexdigest()

    # Enforce unique(key_hash)
    for k in api_keys:
        if k.get("key_hash") == key_hash:
            # extremely unlikely; regenerate once
            plain = "yt_" + "".join(random.choice(string.ascii_letters + string.digits) for _ in range(36))
            key_hash = hashlib.sha256(plain.encode("utf-8")).hexdigest()
            break
    for k in api_keys:
        if k.get("key_hash") == key_hash:
            return _err("CONFLICT", "Generated key collided; retry")

    # Map tool owner_type into schema owner_type (project not allowed in schema; store as service with owner_id namespaced)
    schema_owner_type = owner_type
    schema_owner_id = owner_id
    if owner_type == "project":
        schema_owner_type = "service"
        schema_owner_id = f"project:{owner_id}"

    row = {
        "id": _gen_id("key"),
        "key_hash": key_hash,
        "label": label,
        "owner_type": schema_owner_type,   # schema enum: user/service/anonymous
        "owner_id": schema_owner_id,
        "status": "active",
        "daily_quota_units": int(daily_quota_units),
        "per_minute_request_limit": int(per_minute_request_limit),
        "last_used_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    # Validate schema owner_type compatibility
    if row["owner_type"] not in ["user", "service", "anonymous"]:
        return _err("VALIDATION_ERROR", "owner_type is not compatible with backend schema")

    api_keys.append(row)
    _save("api_keys.json", api_keys)

    return {
        "api_key": row,
        "plain_text_key": plain  # shown only once by this endpoint
    }

def listApiKeys(owner_type=None, owner_id=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool = "listApiKeys"
    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    # Validate
    if owner_type is not None and owner_type not in ["user", "project", "service"]:
        return _err("VALIDATION_ERROR", "owner_type must be one of: user, project, service")
    if owner_id is not None:
        if not isinstance(owner_id, str) or not (1 <= len(owner_id) <= 128):
            return _err("VALIDATION_ERROR", "owner_id must be a non-empty string up to 128 chars")
    if status is not None and status not in ["active", "suspended", "revoked"]:
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    api_keys = _load("api_keys.json")
    req_logs = _load("request_logs.json")

    # Ambient authorization: allow enumeration if any key exists; otherwise unauthorized (matches "refuses if cannot enumerate keys")
    if not isinstance(api_keys, list) or len(api_keys) == 0:
        # log failure (no api_key_id context)
        req_logs.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}",
            "api_key_id": None,
            "tool_name": tool,
            "input": {"owner_type": owner_type, "owner_id": owner_id, "status": status, "limit": limit, "cursor": cursor},
            "status": "failed",
            "youtube_quota_units_charged": 0,
            "error_code": "UNAUTHORIZED",
            "error_message": "No API keys exist to authorize enumeration",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "Caller cannot enumerate keys")

    # Create request log (received)
    api_key_id = api_keys[0].get("id")
    req_id = f"req_{now.strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}"
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool,
        "input": {"owner_type": owner_type, "owner_id": owner_id, "status": status, "limit": limit, "cursor": cursor},
        "status": "received",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    req_logs.append(req_row)
    _save("request_logs.json", req_logs)

    # Rate limit / quota: listing costs 0 units but still counts towards per-minute request limit
    per_min = api_keys[0].get("per_minute_request_limit")
    if not isinstance(per_min, int) or per_min < 0:
        req_row["status"] = "failed"
        req_row["error_code"] = "VALIDATION_ERROR"
        req_row["error_message"] = "API key has invalid limits configured"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "API key has invalid limits configured")

    one_min_ago = now - datetime.timedelta(minutes=1)
    recent = 0
    for r in req_logs:
        if r.get("api_key_id") != api_key_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if dt >= one_min_ago:
            recent += 1
    if per_min == 0 or recent > per_min:
        req_row["status"] = "rate_limited"
        req_row["youtube_quota_units_charged"] = 0
        req_row["error_code"] = "RATE_LIMIT"
        req_row["error_message"] = "Per-minute request limit exceeded"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("request_logs.json", req_logs)
        return _err("RATE_LIMIT", "Per-minute request limit exceeded", limit=per_min)

    # Apply filters (translate project->service/project: prefix)
    def _match(row):
        if not isinstance(row, dict):
            return False
        if status is not None and row.get("status") != status:
            return False
        if owner_type is not None:
            if owner_type == "project":
                if row.get("owner_type") != "service":
                    return False
                if owner_id is not None:
                    return row.get("owner_id") == f"project:{owner_id}"
                return (isinstance(row.get("owner_id"), str) and row.get("owner_id", "").startswith("project:"))
            else:
                if row.get("owner_type") != owner_type:
                    return False
        if owner_id is not None and owner_type != "project":
            if row.get("owner_id") != owner_id:
                return False
        return True

    filtered = [r for r in api_keys if _match(r)]

    # Sort by created_at desc
    def _created_key(r):
        dt = _parse_dt(r.get("created_at"))
        return dt if dt is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    filtered.sort(key=_created_key, reverse=True)

    # Cursor pagination: base64 of {"offset": n}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                offset = obj["offset"]
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(filtered)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    # Mark request as served_from_cache (read)
    req_row["status"] = "served_from_cache"
    req_row["youtube_quota_units_charged"] = 0
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("request_logs.json", req_logs)

    return {
        "api_keys": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

