def setApiKeyStatus(api_key_id, status, reason=None, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # Validate inputs
    if not isinstance(api_key_id, str) or not (1 <= len(api_key_id) <= 64):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string up to 64 chars")
    if status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason must be at most 500 chars")

    api_keys = _load("api_keys.json")
    req_logs = _load("request_logs.json")

    idx = None
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == api_key_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "api_keys row not found", api_key_id=api_key_id)

    row = api_keys[idx]
    cur = row.get("status")
    transitions = {
        "active": ["suspended", "revoked"],
        "suspended": ["active", "revoked"],
        "revoked": []
    }
    if cur not in transitions:
        return _err("VALIDATION_ERROR", "api_keys row has invalid current status", current_status=cur)
    if status == cur:
        # Idempotent: no-op but must still be observable; log the call as served_from_cache
        now = _now()
        log_id = _gen_id("rlog")
        req_logs.append({
            "id": log_id,
            "api_key_id": api_key_id,
            "tool_name": "listRequestLogs",  # best-effort: no dedicated admin tool in enum; use closest read tool
            "input": {"action": "setApiKeyStatus", "api_key_id": api_key_id, "status": status, "reason": reason},
            "status": "served_from_cache",
            "youtube_quota_units_charged": 0,
            "error_code": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", req_logs)
        return {"api_key": row, "idempotent": True}

    if status not in transitions.get(cur, []):
        return _err("CONFLICT", "Requested status transition is not allowed", current_status=cur, target_status=status)

    # Apply transition
    now = _now()
    row["status"] = status
    row["updated_at"] = now
    # Store a lightweight audit note in label if provided (no audit table in schema)
    if reason:
        lbl = row.get("label") or ""
        note = f"[{now}] status->{status}: {reason}"
        if lbl:
            # keep bounded size
            combined = (lbl + " | " + note)
        else:
            combined = note
        row["label"] = combined[-5000:]  # arbitrary safety bound

    api_keys[idx] = row
    _save("api_keys.json", api_keys)

    # Observable dynamics: log the operation (0 quota)
    log_id = _gen_id("rlog")
    req_logs.append({
        "id": log_id,
        "api_key_id": api_key_id,
        "tool_name": "listRequestLogs",  # best-effort within allowed enum
        "input": {"action": "setApiKeyStatus", "api_key_id": api_key_id, "status": status, "reason": reason},
        "status": "fetched_from_youtube",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    _save("request_logs.json", req_logs)

    return {"api_key": row}

def listRequestLogs(api_key_id=None, tool_name=None, status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return _now_dt().isoformat()

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 datetime string")
        try:
            # accept trailing Z
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError(f"{field} must be an RFC3339 datetime string")

    # Validate inputs
    if api_key_id is not None:
        if not isinstance(api_key_id, str) or not (1 <= len(api_key_id) <= 64):
            return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string up to 64 chars")
    if tool_name is not None:
        if not isinstance(tool_name, str) or not (1 <= len(tool_name) <= 64):
            return _err("VALIDATION_ERROR", "tool_name must be a non-empty string up to 64 chars")
    if status is not None and status not in ("received", "served_from_cache", "fetched_from_youtube", "failed", "rate_limited"):
        return _err("VALIDATION_ERROR", "status must be one of: received, served_from_cache, fetched_from_youtube, failed, rate_limited")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    try:
        dt_after = _parse_dt(created_after, "created_after")
        dt_before = _parse_dt(created_before, "created_before")
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))

    if dt_after and dt_before and dt_before < dt_after:
        return _err("VALIDATION_ERROR", "created_before must be >= created_after")

    # AUTH (ambient): allow if there exists any active key in store; optionally restrict to provided api_key_id
    api_keys = _load("api_keys.json")
    if api_key_id is not None:
        ak = next((r for r in api_keys if isinstance(r, dict) and r.get("id") == api_key_id), None)
        if not ak:
            return _err("UNAUTHORIZED", "Not allowed to view logs for the specified api_key_id")
    else:
        ak = next((r for r in api_keys if isinstance(r, dict) and r.get("status") in ("active", "suspended", "revoked")), None)
        if not ak:
            return _err("UNAUTHORIZED", "Not allowed to view request logs")

    # Pagination cursor: base64 encoded JSON {"after_id": "..."} meaning start after this id in sort order
    after_id = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            after_id = obj.get("after_id")
            if after_id is not None and not isinstance(after_id, str):
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    req_logs = _load("request_logs.json")

    # Record call itself (observable dynamics) before returning; use ak.id as best-effort credential context
    call_log_id = _gen_id("rlog")
    call_now = _now()
    req_logs.append({
        "id": call_log_id,
        "api_key_id": ak.get("id"),
        "tool_name": "listRequestLogs",
        "input": {
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "created_after": created_after,
            "created_before": created_before,
            "limit": limit,
            "cursor": cursor
        },
        "status": "served_from_cache",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": call_now,
        "updated_at": call_now
    })
    _save("request_logs.json", req_logs)

    # Filter
    def _dt_of_row(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    rows = [r for r in req_logs if isinstance(r, dict)]
    if api_key_id is not None:
        rows = [r for r in rows if r.get("api_key_id") == api_key_id]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if dt_after is not None:
        rows = [r for r in rows if (_dt_of_row(r) is not None and _dt_of_row(r) >= dt_after)]
    if dt_before is not None:
        rows = [r for r in rows if (_dt_of_row(r) is not None and _dt_of_row(r) < dt_before)]

    # Sort newest first by created_at then id for stability
    def _sort_key(r):
        dt = _dt_of_row(r)
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor
    if after_id:
        # find first occurrence then start after it
        pos = None
        for i, r in enumerate(rows):
            if r.get("id") == after_id:
                pos = i
                break
        if pos is not None:
            rows = rows[pos + 1 :]

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        payload = json.dumps({"after_id": page[-1].get("id")}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    return {
        "data": page,
        "meta": {
            "limit": limit,
            "total_matched": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def getCaller(api_key, **_extra):
    import json, os, datetime, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0130000" if __import__("os").path.isdir("./environment_mix/0130000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return _now_dt().isoformat()

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # Validate input
    if not isinstance(api_key, str) or not (8 <= len(api_key) <= 256):
        return _err("VALIDATION_ERROR", "api_key must be a string between 8 and 256 chars")

    api_keys = _load("api_keys.json")
    req_logs = _load("request_logs.json")

    # Authenticate: must match stored client-visible value or id.
    # Store only has key_hash, so accept api_key matching id as an admin/opaque token,
    # OR accept api_key matching key_hash exactly (treat as client-visible token here).
    ak = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_hash") == api_key:
            ak = r
            break
    if ak is None:
        # Record failed request log with null api_key_id
        now = _now()
        log_id = _gen_id("rlog")
        req_logs.append({
            "id": log_id,
            "api_key_id": None,
            "tool_name": "getVideoDetails",  # best-effort: enum lacks getCaller; log under a supported tool
            "input": {"action": "getCaller"},
            "status": "failed",
            "youtube_quota_units_charged": 0,
            "error_code": "AUTH_ERROR",
            "error_message": "Invalid API key",
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "AUTH_ERROR: missing/invalid API key")

    # Compute usage
    now_dt = _now_dt()
    day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)
    minute_ago = now_dt - datetime.timedelta(minutes=1)

    def _parse_row_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    logs_for_key = [r for r in req_logs if isinstance(r, dict) and r.get("api_key_id") == ak.get("id")]
    used_today = 0
    reqs_last_min = 0
    for r in logs_for_key:
        dt = _parse_row_dt(r.get("created_at"))
        if dt is None:
            continue
        if dt >= day_start:
            q = r.get("youtube_quota_units_charged")
            if isinstance(q, int) and q >= 0:
                used_today += q
        if dt >= minute_ago:
            reqs_last_min += 1

    daily_quota = ak.get("daily_quota_units")
    per_min = ak.get("per_minute_request_limit")
    if not isinstance(daily_quota, int) or daily_quota < 0:
        daily_quota = 0
    if not isinstance(per_min, int) or per_min < 0:
        per_min = 0

    # Update last_used_at only for "successful authenticated request" - treat getCaller as successful
    now = _now()
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == ak.get("id"):
            api_keys[i]["last_used_at"] = now
            api_keys[i]["updated_at"] = now
            ak = api_keys[i]
            break
    _save("api_keys.json", api_keys)

    # Record request log (0 quota)
    log_id = _gen_id("rlog")
    req_logs.append({
        "id": log_id,
        "api_key_id": ak.get("id"),
        "tool_name": "getVideoDetails",  # best-effort: enum lacks getCaller
        "input": {"action": "getCaller"},
        "status": "served_from_cache",
        "youtube_quota_units_charged": 0,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    _save("request_logs.json", req_logs)

    # Return identity/scopes (best-effort; no scopes table in schema)
    return {
        "caller": {
            "api_key_id": ak.get("id"),
            "label": ak.get("label"),
            "owner_type": ak.get("owner_type"),
            "owner_id": ak.get("owner_id"),
            "status": ak.get("status"),
            "scopes": ["youtube.readonly", "transcripts.readonly", "metrics.readonly"]
        },
        "quota": {
            "daily_quota_units": daily_quota,
            "used_today_units": used_today,
            "remaining_today_units": max(daily_quota - used_today, 0)
        },
        "rate_limit": {
            "per_minute_request_limit": per_min,
            "requests_last_minute": reqs_last_min,
            "remaining_this_minute": max(per_min - reqs_last_min, 0)
        }
    }
